{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C03","C20","C24","C04","C05","C06","C12","C13","C22","C30","C16","C25","C29"],
  "contradictory_card_ids": ["C26"],
  "prediction_basis_card_ids": ["C03","C20","C24","C04","C05","C06","C12","C13","C22","C30","C16","C25","C29"],
  "claims": [
    {
      "claim": "Bumetanide, a sulfamoyl anthranilic acid loop diuretic sharing the query's acid-sulfamoyl core, has an absolute oral bioavailability of 95% in cirrhosis patients after oral versus IV dosing (n=8), with L2 context reporting 95-100%.",
      "card_ids": ["C03","C20","C24"]
    },
    {
      "claim": "Cirrhosis-condition contexts for metoclopramide and tolfenamic acid show high oral bioavailability (79-82% and about 100%, respectively), supporting a pattern of high F in cirrhosis.",
      "card_ids": ["C05","C06","C12","C13","C22","C30","C16","C25","C29"]
    },
    {
      "claim": "Azosemide, the closest structural analog (tetrazole/thiophene bioisostere of the query), has an L1 absolute oral bioavailability of 20.4% in fasted healthy humans, meeting the F>=20% threshold; the L2 urinary-recovery estimate of 10% is indirect and does not overturn the L1 value.",
      "card_ids": ["C04","C26"]
    },
    {
      "claim": "L5 gut-wall efflux/intestinal-metabolism records concern 5-ASA, sulfasalazine, AVN 2f, labetalol, and salicylic acid; C60 uses furosemide only as a 1 mM modulator in a sulfasalazine Caco-2 experiment and does not measure furosemide's own permeability or bioavailability; C57/C63/C66 are duplicate representations of the same sulfasalazine/Ko143 experiment. None provide query-specific presystemic-loss evidence.",
      "card_ids": ["C56","C57","C58","C59","C60","C61","C62","C63","C64","C65","C66","C67"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C56","C57","C58","C59","C60","C61","C62","C63","C64","C65","C66","C67"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for furosemide itself is supplied.",
    "No gut-wall efflux or intestinal-metabolism record for furosemide, bumetanide, or azosemide is supplied; L5 records are for unrelated molecules, with C60 using furosemide only as a modulator.",
    "Azosemide was studied in fasted healthy subjects, not cirrhosis, and has conflicting estimates (20.4% L1 absolute vs 10% L2 urinary recovery).",
    "Cirrhosis effects on furosemide-specific transporters and first-pass metabolism are not directly measured.",
    "Furosemide's furan, chloro, and carboxylate groups may alter transporter/metabolic handling relative to bumetanide and azosemide."
  ],
  "decision_summary": "L5 gut-wall efflux/intestinal-metabolism records are for unrelated molecules and do not provide query-specific evidence, so the prior decision is retained. The prediction remains high based on condition-matched high-F analogs (bumetanide 95% in cirrhosis; metoclopramide 79-82%; tolfenamic acid about 100%) and the closest structural analog azosemide at 20.4% L1 absolute F. The indirect azosemide urinary-recovery estimate of 10% and the physicochemical low-permeability prior are insufficient to support F<20%."
}

